    is_nested('[[][]]') ➞ True
    is_nested('[[]][[') ➞ True
    '''
    balance = 0
    for i, char in enumerate(string):
        if char == '[':
            balance += 1
        elif char == ']':
            balance -= 1
            if balance == 0:
                # Check if there's another bracket pair inside this outer pair
                # We need to find if any valid nested structure exists
                pass

    # More direct approach: look for pattern [ ... ] where inside we have at least one pair
    for i in range(len(string) - 1):
        if string[i] == '[' and string[i + 1] == ']':
            # Found a simple pair, check if there's another pair inside
            continue
        if string[i] == '[' and string[i + 1] == '[' and string[i + 2] == ']':
            # Found [[ ]] pattern - nested!
            return True
        if string[i] == '[' and string[i + 1] == '[' and string[i + 2] == '[' and string[i + 3] == ']':
            # Found [[[ ]] pattern - nested!
            return True

    # Better approach: check if any bracket pair has content inside it
    for i in range(len(string) - 1):
        if string[i] == '[' and string[i + 1] == ']':
            # Found a simple pair, skip
            continue
        if string[i] == '[' and string[i + 1] == '[':
            # Check if we have a nested structure
            for j in range(i + 2, len(string)):
                if string[j] == ']':
                    # Check if this closing bracket matches the opening at i
                    # and there's at least one bracket pair inside
                    if string[j - 1] == ']':
                        # Found nested structure
                        return True
                    if string[j - 1] == '[':
                        # Found nested structure
                        return True

    # Alternative: Check if we have a valid balanced string with nesting
    balance = 0
    for char in string:
        if char == '[':
            balance += 1
        elif char == ']':
